import type {MessageCommand,MessageRecord} from '@ziggs-ai/contracts';
export const command = (text='Hello', recipient='person', operationId='operation'):MessageCommand => ({operationId,content:{text},audience:{kind:'explicit',principalIds:[recipient]},deliveries:{kind:'explicit',principalIds:[recipient]},intent:'fyi'});
export const message = (messageId='message', text='Hello', overrides:Partial<MessageRecord>={}):MessageRecord => ({messageId,timestamp:'2026-10-31T00:00:00.000Z',content:{text},sender:{ref:'customer',kind:'user',name:'Customer',isSelf:false},readers:[],recipients:[{ref:'agent',kind:'agent',name:'Agent',isSelf:true}],intent:'request',relationships:{},mandate:null,...overrides});
